import{_ as t,o,c as a,a2 as n}from"./chunks/framework.Do1fvF3d.js";const m=JSON.parse('{"title":"How it works","description":"","frontmatter":{},"headers":[],"relativePath":"en/guia/como-funciona.md","filePath":"en/guia/como-funciona.md","lastUpdated":null}'),r={name:"en/guia/como-funciona.md"};function s(i,e,l,h,c,d){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h1><h2 id="when-a-call-comes-in" tabindex="-1">When a call comes in <a class="header-anchor" href="#when-a-call-comes-in" aria-label="Permalink to &quot;When a call comes in&quot;">​</a></h2><p>Before your phone rings, Tranqui checks the number and shows a card on top of the incoming-call screen:</p><div class="states"><div class="state-contact"><strong>✓ Green</strong>The number is in your contacts. Decided on your phone, without asking anyone.</div><div class="state-identified"><strong>ⓘ Blue</strong>The community knows the number, for example &quot;Pizzería Juan&quot;.</div><div class="state-spam"><strong>⚠ Red</strong>The community reported it as spam, with its label, for example &quot;Spam Claro&quot;.</div><div class="state-unknown"><strong>? Orange</strong>No data, a private number, or no connection.</div></div><p>If a number has several names, the card shows the most used one and you can see the others with <strong>Another name</strong>.</p><p>If nothing answers in time, the call <strong>always rings</strong>: Tranqui never makes you miss a call because of an error.</p><h2 id="blocking" tabindex="-1">Blocking <a class="header-anchor" href="#blocking" aria-label="Permalink to &quot;Blocking&quot;">​</a></h2><ul><li><strong>From the card</strong>, with <strong>Block</strong>. Future calls from that number will not ring.</li><li><strong>Automatically</strong>, if you turn it on in Settings: <ul><li>spam reported by the community,</li><li>private numbers,</li><li>international calls.</li></ul></li></ul><p>Every time we block a call you get a notification with the reason and the time. Your block list stays <strong>only on your phone</strong>.</p><h2 id="after-the-call" tabindex="-1">After the call <a class="header-anchor" href="#after-the-call" aria-label="Permalink to &quot;After the call&quot;">​</a></h2><p>Tranqui asks <strong>&quot;How was this call?&quot;</strong> with two options: <strong>Spam</strong> or <strong>Not spam</strong>. In <strong>History</strong> you can report spam with a label, for example &quot;Spam Claro&quot; or &quot;Debt collection&quot;.</p><p>Each person has a single vote per number; if you change your mind, your vote is updated.</p><h2 id="how-the-community-decides" tabindex="-1">How the community decides <a class="header-anchor" href="#how-the-community-decides" aria-label="Permalink to &quot;How the community decides&quot;">​</a></h2><ul><li>A number is marked as spam when enough people report it and those reports clearly outweigh the &quot;not spam&quot; votes.</li><li>A number saved in many people&#39;s address books is harder to mark as spam, because it shows it belongs to someone known.</li><li>Votes lose weight over time, because numbers get reassigned.</li><li>Accounts younger than 7 days vote with half the weight, to slow down campaigns with fake accounts.</li><li>A name is only shown when <strong>at least 3 different people</strong> used it.</li></ul><h2 id="what-it-needs-on-your-phone" tabindex="-1">What it needs on your phone <a class="header-anchor" href="#what-it-needs-on-your-phone" aria-label="Permalink to &quot;What it needs on your phone&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Permission</th><th>What for</th></tr></thead><tbody><tr><td>Identify and filter calls</td><td>Check who is calling before the phone rings</td></tr><tr><td>Display over other apps</td><td>The colored card on top of the call</td></tr><tr><td>Contacts</td><td>Show people you know in green. Read only on your phone</td></tr><tr><td>Notifications</td><td>Tell you about blocked calls and ask whether a call was spam</td></tr></tbody></table><p>The app explains each permission before asking for it.</p>',17)])])}const p=t(r,[["render",s]]);export{m as __pageData,p as default};
